    )

_SYMBOLS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
    (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)


def to_roman(n):
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999")
    result = ""
    for value, letters in _SYMBOLS:
        while n >= value:
            result += letters
            n -= value
    return result
